def get_session(contact_id):
    if contact_id not in sessions:
        sessions[contact_id] = {
            'route': 'reception',
            'history': [],
        }
    return sessions[contact_id]


def extract_route(reply):
    s = reply.strip()
    try:
        data = json.loads(s)
        if isinstance(data, dict) and 'route' in data:
            return data['route']
    except (json.JSONDecodeError, ValueError):
        pass
    m = re.search(r'\{\s*"route"\s*:\s*"([a-z_]+)"\s*\}', s)
    if m:
        return m.group(1)
    return None


def process_message(contact_id, user_message):
    session = get_session(contact_id)
    session['history'].append({'role': 'user', 'content': user_message})

    current_route = session['route']
    prompt = AGENT_PROMPTS.get(current_route, LUCKY_PROMPT)

    try:
        response = client.messages.create(
            model=MODEL,
            max_tokens=600,
            system=prompt,
            messages=session['history'][-10:],
        )
        reply = response.content[0].text.strip()
    except Exception as e:
        print(f'[AI ERROR] {e}')
        return 'Ð§ÑÐ¾-ÑÐ¾ Ð½Ð° ÑÑÐ¾ÑÐ¾Ð½Ðµ ÑÐ¸ÑÑÐµÐ¼Ñ. ÐÐ°Ð¿Ð¸ÑÐ¸ÑÐµ, Ð¿Ð¾Ð¶Ð°Ð»ÑÐ¹ÑÑÐ°, ÐµÑÑ ÑÐ°Ð· ÑÐµÑÐµÐ· Ð¼Ð¸Ð½ÑÑÑ.'

    session['history'].append({'role': 'assistant', 'content': reply})

    new_route = extract_route(reply)
    if new_route and new_route in AGENT_PROMPTS:
        session['route'] = new_route
        if new_route == 'escalation':
            send_notification(KAREN_CHAT_ID, f'🔴 Клиент {contact_id} передан вам на разбор медицинской ситуации.')
            send_notification(ANNA_CHAT_ID, f'🔴 Эскалация к Карену: клиент {contact_id}.')
        return TRANSITIONS.get(new_route, 'Передаю вас дальше.')

    if any(phrase in reply for phrase in ['передам Карену', 'передаю Карену', 'Карен свяжется', 'передать Карену']):
        saved_history = session['history'].copy()
        def send_summary_notification(history):
            time.sleep(5)
            summary = generate_summary(history)
            karen_text = f'🔴 НОВЫЙ КЛИЕНТ\n\n{summary}'
            anna_text = f'🔴 Эскалация к Карену:\n\n{summary}'
            send_notification(KAREN_CHAT_ID, karen_text)
            send_notification(ANNA_CHAT_ID, anna_text)
        threading.Thread(target=send_summary_notification, args=(saved_history,), daemon=True).start()

    return reply
